import java.nio.file.*;import java.util.*;import android.graphics.Bitmap;import android.graphics.Canvas;import app.morphe.extension.newx.profileimages.ProfileImages;import app.morphe.extension.shared.Utils;
/** Guards overbroad media blocking, original cache reuse, repeated allocation and lost independent settings. */
public class RuntimeTests {
 static int checks;static void ok(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}static long size(float w,float h){return ((long)Float.floatToRawIntBits(w)<<32)|(Float.floatToRawIntBits(h)&0xffffffffL);}
 public static void main(String[] args)throws Exception{
 Utils.directory=Path.of(args[0]);Files.createDirectories(Utils.directory);Path old=Utils.directory.resolve("piko_anonymous_names_v1.properties");if(!Files.exists(old))Files.writeString(old,"secret=untouched\n");String before=Files.readString(old);
 if(args[1].equals("restart")){ok(!ProfileImages.enabled(true)&&ProfileImages.enabled(false),"Independent values survive a separate JVM restart");ProfileImages.set("avatars",true);System.out.println("PASS restart/persistence "+checks);return;}
 ok(ProfileImages.enabled(true)&&ProfileImages.enabled(false),"Both defaults enabled");
 String a="https://pbs.twimg.com/profile_images/123/test_normal.jpg",b="https://pbs.twimg.com/profile_banners/123/456/1500x500";
 for(String s:List.of(a,"http://pbs.twimg.com/profile_images/1/a.jpg","https://PBS.TWIMG.COM/profile_images/1/a.jpg?name=orig","https://abs.twimg.com/sticky/default_profile_images/default_profile.png"))ok(ProfileImages.urlKind(s)==1,"Avatar URL "+s);
 ok(ProfileImages.urlKind(b)==2,"Banner URL");
 for(String s:List.of("https://pbs.twimg.com/media/image.jpg","https://video.twimg.com/amplify_video/1/thumb/a.jpg","https://pbs.twimg.com/tweet_video_thumb/a.jpg","https://pbs.twimg.com/dm_gif_preview/a.jpg","https://abs.twimg.com/emoji/v2/svg/a.svg","https://example.com/profile_images/a.jpg","https://pbs.twimg.com.evil.test/profile_images/a.jpg","https://pbs.twimg.com/media/image.jpg?url=/profile_images/1/a","file:///profile_images/a.jpg","content://local/photo","","not a uri")){ok(ProfileImages.urlKind(s)==0,"Unrelated source untouched "+s);ok(ProfileImages.substitute(s)==s,"Unchanged object identity "+s);}
 Object arbitrary=new Object();ok(ProfileImages.substitute(arbitrary)==arbitrary&&ProfileImages.substitute(null)==null,"Unknown input/null preserved");
 Object na=ProfileImages.substitute(a),nb=ProfileImages.substitute(b);ok(na instanceof Bitmap&&nb instanceof Bitmap&&na!=nb,"Separate local neutral bitmaps");ok(ProfileImages.neutralKind(na)==1&&ProfileImages.neutralKind(nb)==2,"Kind retained without URL lookup");
 for(int i=0;i<10000;i++){ok(ProfileImages.substitute(a)==na,"Avatar bitmap reused");ok(ProfileImages.substitute(b)==nb,"Banner bitmap reused");}ok(Bitmap.allocations==2,"Exactly two allocations");
 ok(!ProfileImages.cacheKey("old-real-image",na).equals("old-real-image"),"Original memory/disk cache bypassed");ok(ProfileImages.cacheKey("tweet-cache",arbitrary).equals("tweet-cache"),"Other cache preserved");ok(ProfileImages.clearPlaceholder(arbitrary,na)==null,"Original placeholder cache excluded");ok(ProfileImages.clearPlaceholder(arbitrary,arbitrary)==arbitrary,"Other placeholder retained");
 Canvas canvas=new Canvas();ProfileImages.draw(canvas,size(80,80),1);ok(canvas.shape.equals("circle")&&Arrays.equals(canvas.coords,new float[]{40,40,40})&&canvas.color==0xff000000,"Black circle in unchanged bounds");ProfileImages.draw(canvas,size(300,100),2);ok(canvas.shape.equals("rect")&&Arrays.equals(canvas.coords,new float[]{0,0,300,100})&&canvas.color==0xff000000,"Black rectangle fills unchanged bounds");
 ok(ProfileImages.blockViewer(a)&&ProfileImages.blockViewer(b),"Profile-only viewer blocked");ok(!ProfileImages.blockViewer("https://pbs.twimg.com/media/a.jpg"),"Tweet viewer not blocked");
 ProfileImages.set("avatars",false);ok(ProfileImages.substitute(a)==a&&ProfileImages.substitute(b)==nb,"Disable avatars independently");ok(!ProfileImages.blockViewer(a)&&ProfileImages.blockViewer(b),"Independent viewer toggles");ProfileImages.set("banners",false);ok(ProfileImages.substitute(b)==b&&ProfileImages.bannerUrl(b)==b,"Disable both restores new requests");ok(ProfileImages.avatarUrl(a)==a,"Original avatar source restored");ok(ProfileImages.neutralKind(na)==1,"Existing neutral never becomes real before restart");
 ProfileImages.set("avatars",true);ok(ProfileImages.avatarUrl(null).equals(ProfileImages.AVATAR),"Missing avatar neutralized");ok(ProfileImages.avatarUrl("https://external.test/user.png").equals(ProfileImages.AVATAR),"Semantic avatar path covers arbitrary host");ok(ProfileImages.avatarViewerUrl(null)==null&&ProfileImages.bannerViewerUrl(null)==null,"Missing photo edit navigation preserved");ProfileImages.set("banners",true);ok(ProfileImages.bannerUrl("https://external.test/banner.png").equals(ProfileImages.BANNER),"Semantic banner path covers arbitrary host");ProfileImages.set("avatars",false);
 ok(before.equals(Files.readString(old)),"Anonymous preferences unchanged");System.out.println("PASS "+checks+" assertions with host graphics/preferences adapters (not Android UI tests)");
 }
}
